//! 🧪️ A real caller's static child keeps its original roots, initiating clock and single paid stock.
use semio_framework_job::*;
use semio_framework_value::{ValueError,ValueRefusalKind};
use std::cell::Cell;
#[global_allocator]
static ORIGINAL_SOURCE_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
thread_local!{static NOW:Cell<u64>=const{Cell::new(1000)};}
fn now()->Option<u64>{Some(NOW.with(Cell::get))}
fn observe<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
fn static_source<T:Send+'static>(_:&T){}
fn metadata()->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,..Default::default()}}
fn work<R>(caller:&mut OriginalJobFixtureCaller,grant:RetainedCloneGrant,fuel:u64,deadline:u64,run:impl FnOnce(&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->Result<R,OriginalTurnFailure>{let mut received=None;caller.turn(grant,|cx|cx.with_original_work_loan(fuel,deadline,|cx|{received=Some(run(cx)?);Ok(())}))?;Ok(received.unwrap())}
#[test]
fn original_owned_caller_source_loan_preserves_static_roots_actual_turn_and_paid_parent_return(){
 let policy:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🎟️caller.json")).unwrap();let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let grant:RetainedCloneGrant=serde_json::from_value(policy["grant"].clone()).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(policy["initialStock"].clone()).unwrap();let close:RetainedCloneGrant=serde_json::from_value(policy["closeGrant"].clone()).unwrap();let operation=OperationId(policy["operation"].as_u64().unwrap());let generation=Generation(policy["generation"].as_u64().unwrap());let fuel=policy["fuel"].as_u64().unwrap();let deadline=policy["deadline"].as_u64().unwrap();
 for cut in policy["cuts"].as_array().unwrap(){NOW.with(|now|now.set(1000));let cut=cut.as_u64().unwrap();let(mut caller,heap)=observe(||OriginalJobFixtureCaller::admit(operation,generation,stock,now,policy["initialDeadline"].as_u64().unwrap(),policy["initialFuel"].as_u64().unwrap()));let mut born=heap.0;assert_eq!(born,caller.born_bytes());let mut foreign_released=0;let(source,ledger)=caller.turn(grant,|cx|Ok((cx.original_source_parent()?.source_identity()?,cx.payload_authority_identity()))).unwrap();
  if cut>0{
   for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(answer,heap)=observe(||work(&mut caller,denied,fuel,deadline,|cx|cx.original_source_parent()?.admit_loan(cx)));assert!(answer.unwrap().is_none());assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());}
   let(answer,heap)=observe(||work(&mut caller,grant,fuel,deadline,|cx|cx.original_source_parent()?.admit_loan(cx)));let mut loan=answer.unwrap().unwrap();static_source(&loan);assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),metadata());let(answer,heap)=observe(||caller.retire_step(close));assert!(answer.is_err());assert_eq!(heap,(0,0));
   if cut==2{
    let(answer,heap)=observe(||work(&mut caller,grant,fuel,deadline,|cx|{let recipient=cx.original_recipient_identity();loan.validate_context(cx)?;loan.run_close(cx,grant,|same|{assert_eq!((same.operation(),same.generation()),(operation,generation));assert_eq!(same.deadline_us(),deadline);assert_eq!(same.fuel_remaining(),fuel);assert!(std::ptr::fn_addr_eq(same.clock_source(),now as fn()->Option<u64>));assert_eq!(same.original_recipient_identity(),recipient);assert_eq!(same.payload_authority_identity(),ledger);let mut target=[0;7];target.copy_from_slice(b"source!");let progress=RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()};same.consume_retained(progress)?;same.consume_fuel(1);Ok(InteractiveJobCloseStep::Pending{progress})})}));let returned=answer.unwrap();assert!(returned.receipt_refusal().is_none());assert_eq!(returned.into_original().unwrap().unwrap().progress(),caller.receipt());assert_eq!(heap,(0,0));
    let(answer,heap)=observe(||work(&mut caller,grant,fuel,deadline,|cx|loan.run_close(cx,grant,|same|{same.consume_retained(metadata())?;let mut failure=OriginalTurnFailure::from(ValueError::literal(ValueRefusalKind::InvalidValue,"original static child failed").with_retained_progress(metadata()));failure.receipt_refusal=Some(ValueError::literal(ValueRefusalKind::DepthLimit,"original static child receipt refused"));Err(failure)})));let failure=answer.unwrap().into_original().unwrap().unwrap_err();assert!(matches!(failure.primary,OriginalTurnPrimary::Value(ref value)if value.message=="original static child failed"));assert_eq!(failure.receipt_refusal.as_ref().unwrap().kind,ValueRefusalKind::DepthLimit);assert_eq!(caller.receipt(),metadata());assert_eq!(heap,(0,0));assert_eq!(observe(||drop(failure)).1,(0,0));
    NOW.with(|now|now.set(1001));for(index,incoming)in law["incoming"].as_array().unwrap().iter().enumerate().skip(1){let fuel=incoming["fuel"].as_u64().unwrap();let deadline=incoming["deadline"].as_u64().unwrap();let(answer,heap)=observe(||work(&mut caller,grant,fuel,deadline,|cx|loan.run_close(cx,grant,|same|{assert_eq!(same.fuel_remaining(),fuel);assert_eq!(same.deadline_us(),deadline);assert!(std::ptr::fn_addr_eq(same.clock_source(),now as fn()->Option<u64>));if index==2{assert!(same.should_yield());return Ok(InteractiveJobCloseStep::Pending{progress:Default::default()})}let mut target=[0;1];target.copy_from_slice(b"Q");let progress=RetainedCloneProgress{copied_items:1,copied_bytes:1,..Default::default()};same.consume_retained(progress)?;same.consume_fuel(1);assert_eq!(same.fuel_remaining(),0);Ok(InteractiveJobCloseStep::Pending{progress})})));let returned=answer.unwrap();assert!(returned.receipt_refusal().is_none());assert_eq!(returned.into_original().unwrap().unwrap().progress(),caller.receipt());assert_eq!(heap,(0,0));}
    let(mut foreign,heap)=observe(||OriginalJobFixtureCaller::admit(operation,generation,stock,now,policy["initialDeadline"].as_u64().unwrap(),policy["initialFuel"].as_u64().unwrap()));born+=heap.0;let(refused,heap)=observe(||foreign.turn(grant,|cx|Ok(loan.validate_context(cx).is_err())));assert!(refused.unwrap());assert_eq!(heap,(0,0));assert_eq!(foreign.receipt(),Default::default());let(released,heap)=observe(||foreign.retire(close));assert_eq!(heap,(0,released));foreign_released+=released;
   }
   caller.cancel().cancel_now();for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(answer,heap)=observe(||work(&mut caller,denied,fuel,deadline,|cx|loan.close_step(cx.original_source_parent()?,cx)));assert_eq!(answer.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert!(!loan.terminal_is_empty());}
   let(answer,heap)=observe(||work(&mut caller,grant,fuel,deadline,|cx|loan.close_step(cx.original_source_parent()?,cx)));assert_eq!(answer.unwrap().progress(),metadata());assert_eq!(caller.receipt(),metadata());assert_eq!(heap,(0,0));assert!(loan.terminal_is_empty());assert_eq!(observe(||drop(loan)).1,(0,0));
  }
  caller.turn(grant,|cx|{assert_eq!(cx.original_source_parent()?.source_identity()?,source);Ok(())}).unwrap();let mut released=foreign_released;for turn in 0..64{if caller.terminal_is_empty(){break}let demand=caller.retirement_demands().unwrap();for denied in [RetainedCloneGrant{maximum_items:0,..close},RetainedCloneGrant{maximum_depth:0,..close},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..close}]{if denied.maximum_release_bytes==0&&demand.release_bytes==0{continue}let(answer,heap)=observe(||caller.retire_step(denied));assert_eq!(answer.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));}let(answer,heap)=observe(||caller.retire_step(close));let progress=answer.unwrap().progress();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.0;released+=heap.1;assert!(turn<63);}assert!(caller.terminal_is_empty());assert_eq!(observe(||drop(caller)).1,(0,0));assert_eq!(born,released);
 }
}
